WITH Src AS (SELECT * FROM store_sales WHERE units > 28 AND units <> 31), store_id_summary AS (SELECT store_id, CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END AS sale_cohort, MIN(sale_date) AS first_sale_date, MIN(sale_date) AS min_sale_date FROM Src GROUP BY store_id, CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT store_id, sale_cohort, first_sale_date, min_sale_date FROM store_id_summary ORDER BY min_sale_date DESC, store_id;
